def is_balanced(s: str) -> bool:
    """True when (), [], {} pairs are properly nested and matched."""
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

# Example:
print(is_balanced('(a[b]{c})'))   # True
print(is_balanced('([)]'))        # False

