languages.go:
func IsBalanced(s string) bool {
    stack := []rune{}
    pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
    for _, ch := range s {
        switch ch {
        case '(', '[', '{':
            stack = append(stack, ch)
        case ')', ']', '}':
            if len(stack) == 0 || stack[len(stack)-1] != pairs[ch] {
                return false
            }
            stack = stack[:len(stack)-1]
        }
    }
    return len(stack) == 0
}

languages.rust:
fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    let pairs = [(')', '('), (']', '['), ('}', '{')];
    for ch in s.chars() {
        match ch {
            '(' | '[' | '{' => stack.push(ch),
            _ => {
                if let Some(&(open, close)) = pairs.iter().find(|&&(c, _)| c == ch) {
                    if stack.pop() != Some(close) {
                        return false;
                    }
                }
            }
        }
    }
    stack.is_empty()
}

