console.log(text.charAt(0).toUpperCase() + text.slice(1));  // Hello WORLD

// Title case:
console.log(text.replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()));
// Hello World

const text = '  hello   world  ';

// Leading and trailing whitespace:
